SourceCode.Declaration:
/// <summary>
/// What a handheld asked to have registered or posted, staged the moment it arrives and worked
/// off separately.
///
/// **Landing is deliberately cheap and everything slow happens afterward.** postProductReceipt
/// and postTransfer used to do the real work - resolving InventTrans, walking InventDim,
/// running the transfer engine - inline, in the same request the operator's device was blocked
/// on. Confirmed live against this tenant: that work can take upwards of a minute when the AOS
/// is under load, which an operator standing at a scanner should never have to wait out. Now
/// that same request does one INSERT and returns; a row here means "received", not "done".
///
/// **Processing runs on its own and on demand.** The recurring batch job
/// HSMobileOpsProcessPendingBatch works every Pending row every few minutes, so work queued on
/// a handheld - offline included - registers even if nobody opens the app again. "Process
/// pending" on the Activity screen does the same at once. Both go through
/// HSMobileOpsPostingService::processCompany, oldest request first, and both can run at the
/// same time: a row is only ever worked by whoever wins [claim].
///
/// Status is one of four values: Pending (staged, not yet attempted), Processing (claimed by a
/// run that is working it now), Registered (or Posted, for a transfer - the real work
/// succeeded), Failed (the real work was attempted and refused - ErrorMessage carries D365FO's
/// own reason). A row never leaves Failed on its own; reprocessing
/// a failed request means the operator submits it again from the device, which lands as a new
/// row under a new idempotency key.
/// </summary>
public class HSMobileOpsPostQueue extends common
{
}

Method.Source:
/// <summary>
/// The staged (or already-processed) request under this idempotency key, if any.
/// </summary>
public static HSMobileOpsPostQueue findByKey(str _idempotencyKey, boolean _forUpdate = false)
{
    HSMobileOpsPostQueue postQueue;

    if (!_idempotencyKey)
    {
        return postQueue;
    }

    postQueue.selectForUpdate(_forUpdate);

    select firstOnly postQueue
        where postQueue.IdempotencyKey == _idempotencyKey;

    return postQueue;
}

/// <summary>
/// Terminal success - a product receipt's registration, a transfer shipment or a transfer
/// receipt, whichever DocumentType this row is. One value covers all three: the device
/// already knows which from the request it sent, and the status list on the Activity screen
/// shows DocumentType alongside it.
/// </summary>
public static str statusRegistered()
{
    return 'Registered';
}

/// <summary>
/// Claimed by a run that is working the row now - see [claim]. Counts as not yet done
/// everywhere Pending does.
/// </summary>
public static str statusProcessing()
{
    return 'Processing';
}

/// <summary>
/// Moves a Pending row to Processing in its own short transaction and says whether this
/// caller won it. The batch job and the "Process pending" button can run at the same time,
/// and both working the same row would post the same receipt or shipment twice; the row
/// lock makes the second caller wait, then find it no longer Pending and leave it alone.
/// ProcessedUtc holds the claim time until the row is finished - see [failInterrupted].
/// </summary>
public static boolean claim(RecId _recId)
{
    HSMobileOpsPostQueue postQueue;
    boolean              won;

    ttsbegin;
    select pessimisticLock firstOnly postQueue
        where postQueue.RecId  == _recId
           && postQueue.Status == HSMobileOpsPostQueue::statusPending();
    if (postQueue.RecId)
    {
        postQueue.Status       = HSMobileOpsPostQueue::statusProcessing();
        postQueue.ProcessedUtc = DateTimeUtil::utcNow();
        postQueue.update();
        won = true;
    }
    ttscommit;

    return won;
}

/// <summary>
/// Fails rows of the current company left in Processing for more than half an hour - a run
/// that died part way (AOS restart, an exception the posting code does not catch). They are
/// not retried: the posting may have committed before its status was written, and working
/// it again could book the same stock twice. A person checks the order instead.
/// </summary>
public static void failInterrupted()
{
    HSMobileOpsPostQueue postQueue;
    utcdatetime          cutoff = DateTimeUtil::addMinutes(DateTimeUtil::utcNow(), -30);

    ttsbegin;
    while select forUpdate postQueue
        where postQueue.Status       == HSMobileOpsPostQueue::statusProcessing()
           && postQueue.ProcessedUtc <  cutoff
    {
        postQueue.Status       = HSMobileOpsPostQueue::statusFailed();
        postQueue.ErrorMessage = 'Processing was interrupted before it finished. Check the order in D365FO before sending it again.';
        postQueue.ProcessedUtc = DateTimeUtil::utcNow();
        postQueue.update();
    }
    ttscommit;
}
